"""Учебная кампания. Решения доступны преподавателю в solutions.py."""

def level(title, topic, chapter, rows, story, task, lesson, starter, hints, requirement=None, password=None):
    width = max(map(len, rows))
    grid = ['#' * (width + 2)] + ['#' + row.ljust(width, '#') + '#' for row in rows] + ['#' * (width + 2)]
    return dict(title=title, topic=topic, chapter=chapter, grid=grid, story=story, task=task, lesson=lesson, starter=starter, hints=hints, requirement=requirement, password=password)

